def semver_sort(versions):
    def parse_version(v):
        # Split build metadata
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse core version
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            identifiers = prerelease.split('.')
            prerelease_parts = []
            for ident in identifiers:
                if ident.isdigit():
                    prerelease_parts.append((0, int(ident)))
                else:
                    prerelease_parts.append((1, ident))
        else:
            prerelease_parts = None

        return (major, minor, patch, prerelease_parts)

    def compare_key(v):
        major, minor, patch, prerelease_parts = parse_version(v)

        # For sorting: version without pre-release sorts after version with pre-release
        # So we use (major, minor, patch, has_prerelease, prerelease_parts)
        # where has_prerelease is False if no pre-release (sorts later) or True if has pre-release
        if prerelease_parts is None:
            return (major, minor, patch, 1)  # 1 means no pre-release, sorts after pre-release
        else:
            return (major, minor, patch, 0, prerelease_parts)  # 0 means has pre-release, sorts before

    return sorted(versions, key=compare_key)

